import type { Localized, Lesson, Flashcard, Question, Activity, Lab, ExternalResource } from '../types';
import type { WeekContent } from '../weekContent';

const L = (en: string, es: string, pt: string): Localized => ({ en, es, pt });
const lesson = (id: string, title: Localized, a: Localized, b: Localized, analogy: Localized, t1: Localized, t2: Localized, check: Localized, options: Localized[], answer: number, why: Localized, pitfall: Localized, fix: Localized, exercises: { title: Localized; prompt: Localized; hint: Localized; solution: Localized; level: 1|2|3 }[], code?: {language:string;caption:Localized;source:string}): Lesson => ({ id, title, minutes: 24, body:[a,b], analogy, takeaways:[t1,t2], check:{question:check,options,answer,explanation:why}, pitfalls:[{mistake:pitfall,fix}], exercises: exercises.map((e,i)=>({id:`${id}-ex${i+1}`,...e})) , ...(code?{code}:{}) });
const card = (id:string, lessonId:string, front:Localized, back:Localized, kind:'concept'|'distinction'='concept'):Flashcard=>({id,lessonId,front,back,kind});
const mc = (id:string, lessonId:string, prompt:Localized, options:Localized[], answer:number, explanation:Localized):Question=>({id,lessonId,type:'multiple-choice',prompt,options,answer,explanation});
const tf = (id:string, lessonId:string, prompt:Localized, answer:boolean, explanation:Localized):Question=>({id,lessonId,type:'true-false',prompt,options:[L('True','Verdadero','Verdadeiro'),L('False','Falso','Falso')],answer:answer?0:1,explanation});
const fill = (id:string, lessonId:string, prompt:Localized, accepted:string[], explanation:Localized):Question=>({id,lessonId,type:'fill-blank',prompt,accepted,explanation});
const short = (id:string, lessonId:string, prompt:Localized, accepted:string[], explanation:Localized):Question=>({id,lessonId,type:'short-answer',prompt,accepted,explanation});
const match = (id:string, lessonId:string, prompt:Localized, left:Localized[], right:Localized[], answer:number[], explanation:Localized):Question=>({id,lessonId,type:'matching',prompt,left,right,answer,explanation});
const order = (id:string, lessonId:string, title:Localized, prompt:Localized, items:Localized[], explanation:Localized):Activity=>({id,lessonId,kind:'order',title,prompt,items,explanation});
const lab = (id:string,title:Localized,goal:Localized,steps:{title:Localized;expected:Localized}[]):Lab=>({id,kind:'design',level:2,title,goal,minutes:35,steps:steps.map((s,i)=>({id:`${id}-s${i+1}`,title:s.title,commands:[],expected:s.expected}))});
const resource = (id:string,title:string,url:string,note:Localized):ExternalResource=>({id,title,url,kind:'article',verifiedOn:'2026-11-04',note});

const lessons: Lesson[] = [
 lesson('hist1-l1',L('Before electronic computers','Antes de las computadoras electrónicas','Antes dos computadores eletrônicos'),
  L('People computed long before electronic machines. Counting boards and mechanical calculators helped with arithmetic, while punched cards controlled patterns in Jacquard looms. These devices automated parts of a task, but they were not general-purpose programmable computers.','Las personas calculaban mucho antes de las máquinas electrónicas. Los tableros de conteo y las calculadoras mecánicas ayudaban con la aritmética, mientras que las tarjetas perforadas controlaban patrones en los telares de Jacquard. Automatizaban partes de una tarea, pero no eran computadoras programables de propósito general.','As pessoas calculavam muito antes das máquinas eletrônicas. Ábacos e calculadoras mecânicas ajudavam na aritmética, enquanto cartões perfurados controlavam padrões nos teares de Jacquard. Esses dispositivos automatizavam partes de uma tarefa, mas não eram computadores programáveis de propósito geral.'),
  L('Charles Babbage designed the Difference Engine to calculate mathematical tables and later described the more general Analytical Engine. Ada Lovelace’s 1843 notes explained a sequence of operations for that proposed machine and considered how it might manipulate symbols beyond numbers. The Analytical Engine was never completed in their lifetimes.','Charles Babbage diseñó la Máquina Diferencial para calcular tablas matemáticas y luego describió la más general Máquina Analítica. En sus notas de 1843, Ada Lovelace explicó una secuencia de operaciones para esa máquina propuesta y consideró cómo podría manipular símbolos además de números. La Máquina Analítica no se completó durante sus vidas.','Charles Babbage projetou a Máquina Diferencial para calcular tabelas matemáticas e depois descreveu a Máquina Analítica, mais geral. Em suas notas de 1843, Ada Lovelace explicou uma sequência de operações para aquela máquina proposta e considerou como ela poderia manipular símbolos além de números. A Máquina Analítica não foi concluída durante a vida dos dois.'),
  L('A mechanical loom can follow a pattern card by card; Babbage imagined a calculating machine that could follow a much richer sequence of instructions.','Um telar mecánico sigue patrones tarjeta por tarjeta; Babbage imaginó una máquina de cálculo capaz de seguir una secuencia de instrucciones mucho más amplia.','Um tear mecânico segue padrões cartão por cartão; Babbage imaginou uma máquina de cálculo capaz de seguir uma sequência de instruções muito mais ampla.'),
  L('Babbage explored machine designs; Lovelace described how instructions could direct a general calculation.','Babbage exploró diseños de máquinas; Lovelace describió cómo las instrucciones podían dirigir un cálculo general.','Babbage explorou projetos de máquinas; Lovelace descreveu como instruções poderiam conduzir um cálculo geral.'),
  L('Separate a proposed design from a built, working machine.','Distingue un diseño propuesto de una máquina construida y funcional.','Diferencie um projeto proposto de uma máquina construída e funcional.'),
  L('Which statement best describes Lovelace’s contribution?','¿Qué afirmación describe mejor el aporte de Lovelace?','Qual afirmação descreve melhor a contribuição de Lovelace?'),
  [L('She wrote notes describing a procedure for the proposed Analytical Engine.','Escribió notas que describían un procedimiento para la Máquina Analítica propuesta.','Ela escreveu notas que descreviam um procedimento para a Máquina Analítica proposta.'),L('She built the first electronic computer.','Construyó la primera computadora electrónica.','Ela construiu o primeiro computador eletrônico.'),L('She invented the transistor.','Inventó el transistor.','Ela inventou o transistor.'),L('She designed the first microprocessor.','Diseñó el primer microprocesador.','Ela projetou o primeiro microprocessador.')],0,
  L('Her 1843 notes describe an algorithmic sequence for a machine that remained a design.','Sus notas de 1843 describen una secuencia algorítmica para una máquina que siguió siendo un diseño.','Suas notas de 1843 descrevem uma sequência algorítmica para uma máquina que permaneceu como projeto.'),
  L('Calling Babbage’s Analytical Engine a completed computer.','Llamar computadora terminada a la Máquina Analítica de Babbage.','Chamar a Máquina Analítica de Babbage de computador concluído.'),
  L('Say “designed” or “proposed” unless discussing a completed machine.','Di “diseñó” o “propuso” salvo que hables de una máquina terminada.','Diga “projetou” ou “propôs”, a menos que esteja falando de uma máquina concluída.'),
  [
   {title:L('Order the early ideas','Ordena las primeras ideas','Ordene as primeiras ideias'),prompt:L('Arrange these from earlier to later.','Ordénalos del más antiguo al más reciente.','Organize do mais antigo para o mais recente.'),hint:L('Think of mechanical calculation before the nineteenth-century designs.','Piensa primero en el cálculo mecánico y luego en los diseños del siglo XIX.','Pense primeiro no cálculo mecânico e depois nos projetos do século XIX.'),solution:L('Counting devices and mechanical calculators precede Babbage’s engines; Lovelace’s notes follow the Analytical Engine proposal.','Los dispositivos de conteo y las calculadoras mecánicas preceden a las máquinas de Babbage; las notas de Lovelace siguen a la propuesta de la Máquina Analítica.','Dispositivos de contagem e calculadoras mecânicas precedem as máquinas de Babbage; as notas de Lovelace vêm depois da proposta da Máquina Analítica.'),level:1},
   {title:L('Design or machine?','¿Diseño o máquina?','Projeto ou máquina?'),prompt:L('Explain why the Analytical Engine matters even though it was not completed.','Explica por qué importa la Máquina Analítica aunque no se completara.','Explique por que a Máquina Analítica é importante mesmo sem ter sido concluída.'),hint:L('Focus on the ideas represented by its plan.','Enfócate en las ideas representadas por su diseño.','Concentre-se nas ideias representadas pelo projeto.'),solution:L('Its design included general-purpose computation and programmable operations, ideas later realized in computers.','Su diseño incluía cálculo de propósito general y operaciones programables, ideas que luego se realizaron en computadoras.','Seu projeto incluía computação de propósito geral e operações programáveis, ideias posteriormente realizadas em computadores.'),level:2}
  ]),
 lesson('hist1-l2',L('From theory to electronic machines','De la teoría a las máquinas electrónicas','Da teoria às máquinas eletrônicas'),
  L('In 1936, Alan Turing described a mathematical model of computation: a simple machine that reads and writes symbols according to rules. It was an abstract model, not a finished computer, but it helped clarify what it means for a procedure to be computable.','En 1936, Alan Turing describió un modelo matemático de computación: una máquina sencilla que lee y escribe símbolos siguiendo reglas. Era un modelo abstracto, no una computadora terminada, pero ayudó a aclarar qué significa que un procedimiento sea computable.','Em 1936, Alan Turing descreveu um modelo matemático de computação: uma máquina simples que lê e escreve símbolos segundo regras. Era um modelo abstrato, não um computador pronto, mas ajudou a esclarecer o que significa um procedimento ser computável.'),
  L('During the 1940s, electronic machines such as ENIAC made large numerical calculations much faster than manual or electromechanical methods. Early systems could require rewiring or switch settings to change a task. Stored-program designs instead keep instructions in memory, allowing a computer to fetch and carry out program steps.','Durante la década de 1940, máquinas electrónicas como ENIAC aceleraron mucho los cálculos numéricos frente a métodos manuales o electromecánicos. Los primeros sistemas podían requerir recableado o ajustes de interruptores para cambiar una tarea. Los diseños de programa almacenado guardan instrucciones en memoria para que la computadora las lea y ejecute.','Durante a década de 1940, máquinas eletrônicas como o ENIAC aceleraram muito os cálculos numéricos em comparação com métodos manuais ou eletromecânicos. Os primeiros sistemas podiam exigir nova ligação de cabos ou ajustes de chaves para mudar uma tarefa. Projetos de programa armazenado mantêm instruções na memória para que o computador as busque e execute.'),
  L('A hand-operated music box follows fixed pins; a stored-program computer can read a different score from memory.','Una caja musical mecánica sigue clavijas fijas; una computadora de programa almacenado puede leer otra partitura desde la memoria.','Uma caixa de música mecânica segue pinos fixos; um computador de programa armazenado pode ler outra partitura da memória.'),
  L('A theory of computation describes what can be computed; a machine implements computation with physical components.','Una teoría de la computación describe qué puede calcularse; una máquina implementa el cálculo con componentes físicos.','Uma teoria da computação descreve o que pode ser calculado; uma máquina implementa o cálculo com componentes físicos.'),
  L('Distinguish a stored program from a machine configured only by rewiring.','Distingue un programa almacenado de una máquina configurada solo mediante cables.','Diferencie um programa armazenado de uma máquina configurada apenas por cabos.'),
  L('What is the key change in a stored-program design?','¿Cuál es el cambio clave de un diseño de programa almacenado?','Qual é a principal mudança em um projeto de programa armazenado?'),
  [L('Instructions can be held in memory and fetched for execution.','Las instrucciones pueden guardarse en memoria y leerse para su ejecución.','As instruções podem ficar na memória e ser buscadas para execução.'),L('The computer no longer needs electrical power.','La computadora ya no necesita energía eléctrica.','O computador deixa de precisar de energia elétrica.'),L('Every task must use punched cards.','Toda tarea debe usar tarjetas perforadas.','Toda tarefa precisa usar cartões perfurados.'),L('Programs become physical gears.','Los programas se convierten en engranajes físicos.','Os programas tornam-se engrenagens físicas.')],0,
  L('Stored instructions make it possible to change a task by loading another program rather than rewiring the machine.','Las instrucciones almacenadas permiten cambiar la tarea al cargar otro programa, en lugar de recablear la máquina.','Instruções armazenadas permitem mudar a tarefa carregando outro programa, em vez de reconectar os cabos da máquina.'),
  L('Treating Turing’s abstract machine as a physical computer that he built.','Tratar la máquina abstracta de Turing como una computadora física que él construyó.','Tratar a máquina abstrata de Turing como um computador físico que ele construiu.'),
  L('Describe Turing’s result as a theoretical model, then connect it to later machines.','Describe el resultado de Turing como un modelo teórico y luego relaciónalo con máquinas posteriores.','Descreva o resultado de Turing como um modelo teórico e depois conecte-o a máquinas posteriores.'),
  [
   {title:L('Compare programming methods','Compara métodos de programación','Compare métodos de programação'),prompt:L('Name one practical difference between rewiring and a stored program.','Nombra una diferencia práctica entre recablear y usar un programa almacenado.','Cite uma diferença prática entre reconectar cabos e usar um programa armazenado.'),hint:L('Ask what changes when a new task arrives.','Piensa qué cambia cuando llega una nueva tarea.','Pense no que muda quando surge uma nova tarefa.'),solution:L('Rewiring changes physical connections; a stored-program machine can change tasks by loading different instructions into memory.','El recableado cambia conexiones físicas; una máquina de programa almacenado puede cambiar de tarea al cargar otras instrucciones en memoria.','Reconectar cabos muda conexões físicas; uma máquina de programa armazenado pode mudar de tarefa ao carregar outras instruções na memória.'),level:1},
   {title:L('Explain abstraction','Explica la abstracción','Explique a abstração'),prompt:L('How does Turing’s model help us reason about computers without describing a specific machine?','¿Cómo ayuda el modelo de Turing a razonar sobre computadoras sin describir una máquina específica?','Como o modelo de Turing ajuda a raciocinar sobre computadores sem descrever uma máquina específica?'),hint:L('Separate rules for computation from hardware details.','Separa las reglas del cálculo de los detalles del hardware.','Separe as regras de computação dos detalhes do hardware.'),solution:L('It gives a simplified rule-based model for studying which procedures are computable, independent of a particular physical design.','Ofrece un modelo simplificado basado en reglas para estudiar qué procedimientos son computables, sin depender de un diseño físico concreto.','Ele oferece um modelo simplificado baseado em regras para estudar quais procedimentos são computáveis, sem depender de um projeto físico específico.'),level:2}
  ]),
 lesson('hist1-l3',L('Smaller components, wider access','Componentes más pequeños, mayor acceso','Componentes menores, acesso mais amplo'),
  L('Vacuum tubes, transistors, and integrated circuits mark important changes in how electronic computers were built. Transistors were smaller and used less power than vacuum tubes. Integrated circuits placed multiple electronic components together on a small piece of semiconductor material.','Las válvulas de vacío, los transistores y los circuitos integrados marcan cambios importantes en la construcción de computadoras electrónicas. Los transistores eran más pequeños y consumían menos energía que las válvulas. Los circuitos integrados reúnen varios componentes electrónicos en una pequeña pieza de material semiconductor.','Válvulas, transistores e circuitos integrados marcam mudanças importantes na construção de computadores eletrônicos. Os transistores eram menores e consumiam menos energia que as válvulas. Circuitos integrados reúnem vários componentes eletrônicos em uma pequena peça de material semicondutor.'),
  L('As components shrank and became more reliable, computers could become smaller and more affordable. Microprocessors put a computer’s central processing functions onto a chip. Personal computers then brought computing to homes, schools, and small businesses, while networking connected machines and users.','A medida que los componentes se hicieron más pequeños y confiables, las computadoras pudieron reducir su tamaño y costo. Los microprocesadores reunieron funciones centrales de procesamiento en un chip. Las computadoras personales acercaron la computación a hogares, escuelas y pequeñas empresas, mientras que las redes conectaron máquinas y usuarios.','À medida que os componentes ficaram menores e mais confiáveis, os computadores puderam diminuir de tamanho e custo. Microprocessadores reuniram funções centrais de processamento em um chip. Computadores pessoais levaram a computação a casas, escolas e pequenas empresas, enquanto redes conectaram máquinas e usuários.'),
  L('Replacing a room of equipment with a single chip is like replacing a workshop of separate tools with one compact multipurpose tool.','Sustituir una sala de equipos por un solo chip se parece a reemplazar un taller de herramientas separadas por una herramienta compacta y multipropósito.','Substituir uma sala de equipamentos por um único chip é como trocar uma oficina de ferramentas separadas por uma ferramenta compacta e multifuncional.'),
  L('Advances in components changed cost, size, reliability, and the number of people who could use computers.','Los avances en componentes cambiaron el costo, tamaño, confiabilidad y cantidad de personas que podían usar computadoras.','Avanços nos componentes mudaram custo, tamanho, confiabilidade e o número de pessoas que podiam usar computadores.'),
  L('Connect technical change to its social effect without treating one invention as the sole cause.','Relaciona el cambio técnico con su efecto social sin atribuir todo a un solo invento.','Relacione a mudança técnica ao efeito social sem atribuir tudo a uma única invenção.'),
  L('Why did smaller and more reliable components matter historically?','¿Por qué importaron históricamente los componentes más pequeños y confiables?','Por que componentes menores e mais confiáveis foram importantes historicamente?'),
  [L('They helped make computers smaller, more reliable, and available to more users.','Ayudaron a que las computadoras fueran más pequeñas, confiables y accesibles a más usuarios.','Ajudaram a tornar os computadores menores, mais confiáveis e acessíveis a mais pessoas.'),L('They made programs unnecessary.','Hicieron innecesarios los programas.','Tornaram os programas desnecessários.'),L('They ended the need for networks.','Eliminaron la necesidad de redes.','Eliminaram a necessidade de redes.'),L('They prevented computers from being used for business.','Impidiendo el uso de computadoras en empresas.','Impediram o uso de computadores em empresas.')],0,
  L('Component miniaturization supported more compact systems and broader adoption, though software and networks also mattered.','La miniaturización permitió sistemas más compactos y una adopción más amplia, aunque también importaron el software y las redes.','A miniaturização permitiu sistemas mais compactos e adoção mais ampla, embora software e redes também tenham sido importantes.'),
  L('Explaining personal computing as the result of one invention alone.','Explicar la computación personal como resultado de un solo invento.','Explicar a computação pessoal como resultado de uma única invenção.'),
  L('Mention several linked changes: components, manufacturing, software, cost, and distribution.','Menciona varios cambios conectados: componentes, fabricación, software, costo y distribución.','Mencione várias mudanças conectadas: componentes, fabricação, software, custo e distribuição.'),
  [
   {title:L('Cause and effect','Causa y efecto','Causa e efeito'),prompt:L('Draw a three-step chain linking smaller components to broader computer use.','Dibuja una cadena de tres pasos que conecte componentes menores con un uso más amplio.','Desenhe uma cadeia de três etapas que ligue componentes menores a um uso mais amplo.'),hint:L('Include size, price, and who can access the system.','Incluye tamaño, precio y quién puede acceder al sistema.','Inclua tamanho, preço e quem pode acessar o sistema.'),solution:L('Smaller components can enable compact machines; compact production can lower cost; lower cost can expand access to homes, schools, and businesses.','Los componentes pequeños permiten máquinas compactas; producir equipos compactos puede reducir el costo; un menor costo amplía el acceso a hogares, escuelas y empresas.','Componentes menores podem permitir máquinas compactas; a produção compacta pode reduzir custos; custos menores ampliam o acesso a casas, escolas e empresas.'),level:2},
   {title:L('Compare eras','Compara épocas','Compare épocas'),prompt:L('Compare a centralized mainframe environment with a personal-computer environment.','Compara un entorno de mainframe centralizado con uno de computadoras personales.','Compare um ambiente de mainframe centralizado com um ambiente de computadores pessoais.'),hint:L('Consider where the machine sits and who uses it directly.','Considera dónde está la máquina y quién la usa directamente.','Considere onde fica a máquina e quem a utiliza diretamente.'),solution:L('A mainframe serves many people through terminals and centralized operations; a personal computer gives an individual or small group direct access to a local machine.','Un mainframe sirve a muchas personas mediante terminales y operaciones centralizadas; una computadora personal da acceso directo a una máquina local a una persona o grupo pequeño.','Um mainframe atende muitas pessoas por terminais e operações centralizadas; um computador pessoal dá acesso direto a uma máquina local para uma pessoa ou pequeno grupo.'),level:2}
  ],
  {language:'text',caption:L('A compact timeline of selected milestones','Cronología breve de hitos seleccionados','Linha do tempo breve de marcos selecionados'),source:'1843  Lovelace publishes notes on the Analytical Engine\n1936  Turing describes an abstract model of computation\n1940s  Electronic computers such as ENIAC are built\n1948  A stored-program computer runs a program\n1969  ARPANET begins operating\n1970s–1980s  Microprocessor-based personal computing expands access\n1989–1990  The Web is proposed and prototyped'}),
 lesson('hist1-l4',L('Networks, internet, and the Web','Redes, Internet y la Web','Redes, Internet e Web'),
  L('Computer networks let separate machines exchange data. ARPANET began operating in 1969 as an early packet-switched network. The Internet grew through the interconnection of networks using shared protocols; it is not the same thing as the Web.','Las redes permiten que máquinas separadas intercambien datos. ARPANET comenzó a operar en 1969 como una de las primeras redes de conmutación de paquetes. Internet creció al interconectar redes mediante protocolos compartidos; no es lo mismo que la Web.','Redes permitem que máquinas separadas troquem dados. A ARPANET começou a operar em 1969 como uma das primeiras redes de comutação de pacotes. A Internet cresceu ao interconectar redes com protocolos compartilhados; ela não é a mesma coisa que a Web.'),
  L('Tim Berners-Lee proposed the Web at CERN in 1989 and prototyped the first browser and server in 1990. The Web uses Internet connectivity to link and serve resources such as pages. Later mobile devices, cloud services, and always-on networks made software services part of ordinary daily life.','Tim Berners-Lee propuso la Web en CERN en 1989 y creó un prototipo del primer navegador y servidor en 1990. La Web usa la conectividad de Internet para enlazar y servir recursos como páginas. Más tarde, los dispositivos móviles, servicios en la nube y redes permanentes integraron servicios de software a la vida cotidiana.','Tim Berners-Lee propôs a Web no CERN em 1989 e criou um protótipo do primeiro navegador e servidor em 1990. A Web usa a conectividade da Internet para vincular e servir recursos como páginas. Mais tarde, dispositivos móveis, serviços em nuvem e redes sempre disponíveis integraram serviços de software à vida cotidiana.'),
  L('The Internet is a road network; the Web is one service that uses those roads to connect documents and applications.','Internet es una red de carreteras; la Web es un servicio que usa esas carreteras para conectar documentos y aplicaciones.','A Internet é uma rede de estradas; a Web é um serviço que usa essas estradas para conectar documentos e aplicações.'),
  L('The Web depends on the Internet, but other services also use the Internet.','La Web depende de Internet, pero otros servicios también usan Internet.','A Web depende da Internet, mas outros serviços também usam a Internet.'),
  L('Avoid using “Internet” and “Web” as interchangeable terms.','Evita usar “Internet” y “Web” como términos intercambiables.','Evite usar “Internet” e “Web” como termos equivalentes.'),
  L('Which statement is accurate?','¿Qué afirmación es correcta?','Qual afirmação está correta?'),
  [L('The Web is a system of linked resources that operates over the Internet.','La Web es un sistema de recursos enlazados que funciona sobre Internet.','A Web é um sistema de recursos ligados que funciona pela Internet.'),L('The Internet and the Web are identical.','Internet y la Web son idénticas.','Internet e Web são idênticas.'),L('The Web existed before computer networks.','La Web existía antes de las redes de computadoras.','A Web existia antes das redes de computadores.'),L('ARPANET was the first Web browser.','ARPANET fue el primer navegador web.','ARPANET foi o primeiro navegador da Web.')],0,
  L('The Web is one application system built on Internet networking.','La Web es un sistema de aplicaciones que usa redes de Internet.','A Web é um sistema de aplicações construído sobre as redes da Internet.'),
  L('Saying the Web was invented at the same time as the Internet.','Decir que la Web se inventó al mismo tiempo que Internet.','Dizer que a Web foi inventada ao mesmo tempo que a Internet.'),
  L('Keep their roles distinct: network infrastructure versus linked information service.','Distingue sus funciones: infraestructura de red frente a servicio de información enlazada.','Diferencie suas funções: infraestrutura de rede versus serviço de informação interligada.'),
  [
   {title:L('Sort the terms','Clasifica los términos','Classifique os termos'),prompt:L('Place each item under network infrastructure or Web service.','Ubica cada elemento bajo infraestructura de red o servicio web.','Coloque cada item em infraestrutura de rede ou serviço da Web.'),hint:L('Internet protocols carry traffic; Web pages use links.','Los protocolos de Internet transportan tráfico; las páginas web usan enlaces.','Protocolos da Internet transportam tráfego; páginas da Web usam links.'),solution:L('TCP/IP and routers belong to Internet infrastructure; browsers, URLs, and linked pages are associated with the Web.','TCP/IP y los enrutadores pertenecen a la infraestructura de Internet; los navegadores, URL y páginas enlazadas se asocian con la Web.','TCP/IP e roteadores pertencem à infraestrutura da Internet; navegadores, URLs e páginas ligadas estão associados à Web.'),level:1},
   {title:L('Why networking matters','Por qué importan las redes','Por que as redes importam'),prompt:L('Give one way networking changed software use.','Da un ejemplo de cómo las redes cambiaron el uso del software.','Dê um exemplo de como as redes mudaram o uso do software.'),hint:L('Consider shared services or collaboration.','Considera servicios compartidos o colaboración.','Considere serviços compartilhados ou colaboração.'),solution:L('Networks enabled remote access, distributed collaboration, and services delivered from systems users do not own locally.','Las redes permitieron acceso remoto, colaboración distribuida y servicios ofrecidos desde sistemas que los usuarios no poseen localmente.','Redes permitiram acesso remoto, colaboração distribuída e serviços oferecidos por sistemas que os usuários não possuem localmente.'),level:2}
  ]),
 lesson('hist1-l5',L('Reading computing history as change','Leer la historia de la computación como cambio','Ler a história da computação como mudança'),
  L('Computing history is not just a list of inventions. Changes in hardware, software, users, organizations, and communication reinforce one another. A smaller computer matters more when people can afford it, programs are useful, and networks make it easier to share information.','La historia de la computación no es solo una lista de inventos. Los cambios en hardware, software, usuarios, organizaciones y comunicación se refuerzan entre sí. Una computadora más pequeña importa más cuando la gente puede pagarla, los programas son útiles y las redes facilitan compartir información.','A história da computação não é apenas uma lista de invenções. Mudanças em hardware, software, usuários, organizações e comunicação se reforçam. Um computador menor importa mais quando as pessoas podem comprá-lo, os programas são úteis e as redes facilitam compartilhar informação.'),
  L('A useful historical explanation names a change, identifies pressures or enabling conditions, and describes consequences. It also avoids saying that a single inventor or device caused every later development. Technologies often emerge through many contributors, prototypes, standards, and communities.','Una explicación histórica útil nombra un cambio, identifica presiones o condiciones que lo hicieron posible y describe consecuencias. También evita afirmar que una sola persona o dispositivo causó todos los avances posteriores. Las tecnologías suelen surgir gracias a muchos colaboradores, prototipos, estándares y comunidades.','Uma explicação histórica útil nomeia uma mudança, identifica pressões ou condições que a tornaram possível e descreve consequências. Também evita dizer que uma pessoa ou dispositivo causou todos os avanços posteriores. Tecnologias costumam surgir do trabalho de muitos colaboradores, protótipos, padrões e comunidades.'),
  L('A computing timeline is like a map: it shows milestones, but an explanation also needs roads between them.','Una cronología de computación es como un mapa: muestra hitos, pero una explicación también necesita los caminos entre ellos.','Uma linha do tempo da computação é como um mapa: mostra marcos, mas uma explicação também precisa dos caminhos entre eles.'),
  L('Historical causation is usually shared across technical and social conditions.','Las causas históricas suelen combinar condiciones técnicas y sociales.','As causas históricas costumam combinar condições técnicas e sociais.'),
  L('Use evidence and qualify claims about “the first” or “the cause.”','Usa evidencia y matiza las afirmaciones sobre “el primero” o “la causa”.','Use evidências e qualifique afirmações sobre “o primeiro” ou “a causa”.'),
  L('What makes a historical explanation stronger than a list of dates?','¿Qué hace que una explicación histórica sea mejor que una lista de fechas?','O que torna uma explicação histórica melhor do que uma lista de datas?'),
  [L('It connects a change to its context, causes, and consequences.','Conecta un cambio con su contexto, causas y consecuencias.','Ela conecta uma mudança ao seu contexto, causas e consequências.'),L('It includes the greatest number of dates.','Incluye la mayor cantidad posible de fechas.','Inclui o maior número possível de datas.'),L('It credits every outcome to one famous person.','Atribuye cada resultado a una sola persona famosa.','Atribui cada resultado a uma única pessoa famosa.'),L('It avoids evidence so the story is simpler.','Evita la evidencia para simplificar la historia.','Evita evidências para simplificar a história.')],0,
  L('Historical analysis explains relationships and uses evidence rather than only naming events.','El análisis histórico explica relaciones y usa evidencia en vez de solo nombrar eventos.','A análise histórica explica relações e usa evidências em vez de apenas nomear eventos.'),
  L('Treating chronology as proof of cause.','Tratar la cronología como prueba de causalidad.','Tratar a cronologia como prova de causalidade.'),
  L('Ask what mechanism links events and what other conditions mattered.','Pregunta qué mecanismo conecta los hechos y qué otras condiciones influyeron.','Pergunte qual mecanismo conecta os acontecimentos e quais outras condições importaram.'),
  [
   {title:L('Write a causal link','Escribe un vínculo causal','Escreva uma relação causal'),prompt:L('Write two sentences linking one hardware change to a change in users or practice.','Escribe dos oraciones que relacionen un cambio de hardware con un cambio en usuarios o prácticas.','Escreva duas frases ligando uma mudança de hardware a uma mudança entre usuários ou práticas.'),hint:L('Use “helped enable,” not “single-handedly caused.”','Usa “ayudó a permitir”, no “causó por sí solo”.','Use “ajudou a permitir”, não “causou sozinho”.'),solution:L('Example: integrated circuits helped make computers more compact. Alongside manufacturing and software changes, lower costs contributed to wider personal use.','Ejemplo: los circuitos integrados ayudaron a hacer las computadoras más compactas. Junto con cambios de fabricación y software, la reducción de costos contribuyó a un uso personal más amplio.','Exemplo: circuitos integrados ajudaram a tornar computadores mais compactos. Junto com mudanças na fabricação e no software, custos menores contribuíram para um uso pessoal mais amplo.'),level:2},
   {title:L('Check a timeline claim','Verifica una afirmación cronológica','Verifique uma afirmação cronológica'),prompt:L('Choose one claim in the week and name the kind of source that could verify it.','Elige una afirmación de la semana y nombra el tipo de fuente que podría verificarla.','Escolha uma afirmação da semana e indique que tipo de fonte poderia verificá-la.'),hint:L('Prefer a museum, professional society, or primary archive for historical claims.','Prefiere un museo, una sociedad profesional o un archivo primario para afirmaciones históricas.','Prefira um museu, sociedade profissional ou arquivo primário para afirmações históricas.'),solution:L('A museum timeline or primary document can verify a milestone date; a second independent source can help confirm context and wording.','Una cronología de museo o documento primario puede verificar la fecha de un hito; una segunda fuente independiente ayuda a confirmar contexto y formulación.','Uma linha do tempo de museu ou documento primário pode verificar a data de um marco; uma segunda fonte independente ajuda a confirmar contexto e formulação.'),level:3}
  ])
];

